final ValueNotifier<Locale> appLocaleNotifier = ValueNotifier<Locale>(const Locale('en'));

class FallbackMaterialLocalizationsDelegate extends LocalizationsDelegate<MaterialLocalizations> {
  const FallbackMaterialLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) => true;

  @override
  Future<MaterialLocalizations> load(Locale locale) =>
      SynchronousFuture<MaterialLocalizations>(const DefaultMaterialLocalizations());

  @override
  bool shouldReload(FallbackMaterialLocalizationsDelegate old) => false;
}

class FallbackCupertinoLocalizationsDelegate extends LocalizationsDelegate<CupertinoLocalizations> {
  const FallbackCupertinoLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) => true;

  @override
  Future<CupertinoLocalizations> load(Locale locale) =>
      SynchronousFuture<CupertinoLocalizations>(const DefaultCupertinoLocalizations());

  @override
  bool shouldReload(FallbackCupertinoLocalizationsDelegate old) => false;
}

class AppLanguage {
  static const Map<String, String> supportedLanguages = {
    'en': 'English',
    'hi': 'Hindi (हिंदी)',
    'ml': 'Malayalam (മലയാളം)',
    'ta': 'Tamil (தமிழ்)',
    'te': 'Telugu (తెలుగు)',
    'kn': 'Kannada (കನ್ನಡ)',
  };

  static String currentLanguageCode = 'en';

  static void initLanguage() {
    currentLanguageCode = StorageService.getLanguageCode();
    appLocaleNotifier.value = Locale(currentLanguageCode);
  }

  static Future<void> setLanguage(String code) async {
    if (!supportedLanguages.containsKey(code)) return;
    currentLanguageCode = code;
    await StorageService.saveLanguageCode(code);
    appLocaleNotifier.value = Locale(code);
  }

  static String getLanguageName(String code) {
    return supportedLanguages[code] ?? 'English';
  }

  static int languageCodeToInt(String code) {
    switch (code.trim().toLowerCase()) {
      case 'hi':
      case 'hindi':
      case '2':
        return 2;
      case 'ml':
      case 'malayalam':
      case '3':
        return 3;
      case 'ta':
      case 'tamil':
      case '4':
        return 4;
      case 'te':
      case 'telugu':
      case '5':
        return 5;
      case 'kn':
      case 'kannada':
      case '6':
        return 6;
      case 'en':
      case 'english':
      case '1':
      default:
        return 1;
    }
  }

  static String languageCodeFromInt(int id) {
    switch (id) {
      case 2:
        return 'hi';
      case 3:
        return 'ml';
      case 4:
        return 'ta';
      case 5:
        return 'te';
      case 6:
        return 'kn';
      case 1:
      default:
        return 'en';
    }
  }

  static String tr(BuildContext context, String key) {
    return trCode(key);
  }

  static String trParams(BuildContext context, String key, Map<String, String> params) {
    return trCode(key, params: params);
  }

  static String trCode(String key, {Map<String, String>? params}) {
    final code = appLocaleNotifier.value.languageCode;
    final dict = _translations[code] ?? _translations['en']!;
    var text = dict[key] ?? _translations['en']![key] ?? key;
    if (params != null && params.isNotEmpty) {
      params.forEach((k, v) {
        text = text.replaceAll('{$k}', v);
      });
    }
    return text;
  }

